/**
 * @name Cleartext sensitive information in logs
 * @description Logging sensitive information such as keys or passwords in cleartext can lead to information disclosure.
 * @kind path-problem
 * @problem.severity error
 * @id py/cleartext-logging
 * @tags security
 *       external/cwe/cwe-532
 *       external/cwe/cwe-312
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs
import semmle.python.Concepts

module CleartextLoggingConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // print(sink)
      (
        call = API::builtin("print").getACall() and
        sink = call.getArg(_)
      )
      or
      // logging.info(sink)
      (
        call = API::moduleImport("logging").getMember(["debug", "info", "warning", "error", "critical", "log"]).getACall() and
        sink = call.getArg(_)
      )
      or
      // logger.info(sink)
      (
        call = API::moduleImport("logging").getMember("getLogger").getACall().getReturn().getMember(["debug", "info", "warning", "error", "critical", "log"]).getACall() and
        sink = call.getArg(_)
      )
    )
  }
}

module CleartextLoggingFlow = TaintTracking::Global<CleartextLoggingConfig>;
import CleartextLoggingFlow::PathGraph

from CleartextLoggingFlow::PathNode source, CleartextLoggingFlow::PathNode sink
where CleartextLoggingFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Sensitive information logged from $@.", source.getNode(), "user input"
